def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

print(gcd(1071, 462))   # 21

def bubble_sort(a):
    a = list(a)
    for end in range(len(a) - 1, 0, -1):
        swapped = False
        for i in range(end):
            if a[i] > a[i + 1]:
                a[i], a[i + 1] = a[i + 1], a[i]
                swapped = True
        if not swapped:
            break
    return a

print(bubble_sort([5, 2, 9, 1, 5, 6]))   # [1, 2, 5, 5, 6, 9]

def insertion_sort(a):
    a = list(a)
    for i in range(1, len(a)):
        item, j = a[i], i - 1
        while j >= 0 and a[j] > item:
            a[j + 1] = a[j]        # shift larger items right
            j -= 1
        a[j + 1] = item
    return a

print(insertion_sort([5, 2, 9, 1, 5, 6]))   # [1, 2, 5, 5, 6, 9]

def merge_sort(a):
    if len(a) <= 1:
        return a
    mid = len(a) // 2
    left, right = merge_sort(a[:mid]), merge_sort(a[mid:])
    out, i, j = [], 0, 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:          # <= keeps equal items in order
            out.append(left[i]); i += 1
        else:
            out.append(right[j]); j += 1
    return out + left[i:] + right[j:]

print(merge_sort([38, 27, 43, 3, 9, 82, 10]))   # [3, 9, 10, 27, 38, 43, 82]

import random

def quicksort(a):
    if len(a) <= 1:
        return a
    pivot = random.choice(a)
    smaller = [x for x in a if x < pivot]
    equal   = [x for x in a if x == pivot]
    larger  = [x for x in a if x > pivot]
    return quicksort(smaller) + equal + quicksort(larger)

print(quicksort([33, 10, 55, 71, 29, 3, 18]))   # [3, 10, 18, 29, 33, 55, 71]

def heapsort(a):
    a = list(a)
    n = len(a)

    def sift_down(root, end):
        while (child := 2 * root + 1) < end:
            if child + 1 < end and a[child + 1] > a[child]:
                child += 1
            if a[root] >= a[child]:
                return
            a[root], a[child] = a[child], a[root]
            root = child

    for start in range(n // 2 - 1, -1, -1):
        sift_down(start, n)
    for end in range(n - 1, 0, -1):
        a[0], a[end] = a[end], a[0]
        sift_down(0, end)
    return a

print(heapsort([12, 11, 13, 5, 6, 7]))   # [5, 6, 7, 11, 12, 13]

def counting_sort(a, k):
    counts = [0] * (k + 1)
    for x in a:
        counts[x] += 1
    out = []
    for value, c in enumerate(counts):
        out.extend([value] * c)
    return out

print(counting_sort([4, 2, 2, 8, 3, 3, 1], 8))   # [1, 2, 2, 3, 3, 4, 8]

def radix_sort(nums):
    place = 1
    while place <= max(nums):
        buckets = [[] for _ in range(10)]
        for n in nums:
            buckets[(n // place) % 10].append(n)   # stable by construction
        nums = [n for b in buckets for n in b]
        place *= 10
    return nums

print(radix_sort([170, 45, 75, 90, 802, 24, 2, 66]))   # [2, 24, 45, 66, 75, 90, 170, 802]
